43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
45	
46	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	/** Percentages are applied as integer arithmetic so that the final
56	 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
57	const addPercent = (amount: number, percent: number): number =>
58	  amount + (amount * percent) / 100;
59	
60	/** Rounds up — premiums round in the MHPCO's favour. */
61	const roundPremium = (amount: number): number => Math.ceil(amount);
62	
63	const itemBasePremium = (item: Item): number =>
64	  BASE_PREMIUM_BY_TYPE[item.type];
65	
66	const policyBasePremium = (items: Item[]): number =>
67	  items.reduce((total, item) => total + itemBasePremium(item), 0);
68	
69	const quote = (items: Item[]): StepResult => {
70	  const basePremium = policyBasePremium(items);
71	  const modifiedPremium = addPercent(
72	    basePremium,
73	    FIRST_INSURANCE_SURCHARGE_PERCENT,
74	  );
75	  // The processing fee is added last, after all percentage modifiers.
76	  const premium = modifiedPremium + PROCESSING_FEE;
77	  return { premium: roundPremium(premium) };
78	};
79	
80	const runStep = (step: Step): StepResult => {
81	  if (step.op === "quote") return quote(step.items);
82	  throw new Error(`Unsupported step: ${step.op}`);
83	};
84	
85	export const runScenario = (scenario: Scenario): ScenarioResult => {
86	  const results = scenario.steps.map(runStep);
87	  return { results };
88	};
